 public static class SignBoardsIntake {
  const string Source=CatalogPreparation.Root+"/Sources/AlpineSignBoards/", Logs="Logs/AlpineSignBoards", Request="Logs/ImportSignBoards.request";
  const string Hash="A533FFDEB2781572932C7FAC07F0FC6312B600D50133BD23607DAF399DD22A12";
  [Serializable]public class Export {public Sign[] signs;}
  [Serializable]public class Sign {public string index,name,model;public int triangles;public float[] size,low,high;}
  static T[] All<T>(Scene scene)where T:Component=>scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static bool IsSign(CatalogPlacement p)=>p&&(p.assetId??"").StartsWith("alpine-sign-",StringComparison.Ordinal);
  static void Require(bool condition,string message){if(!condition)throw new InvalidOperationException("Sign intake: "+message);}
  static string Pose(Transform t)=>t.localToWorldMatrix.ToString("R");
  [InitializeOnLoadMethod]static void Reload(){EditorApplication.update+=Pending;}
  static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Install();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static Material Palette(){string path=Source+"SignPalette.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Simple Lit"));AssetDatabase.CreateAsset(m,path);}m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Source+"Palette.png"));m.SetColor("_BaseColor",Color.white);m.SetColor("_SpecColor",Color.black);m.SetFloat("_Smoothness",0);m.SetFloat("_Surface",0);m.SetFloat("_ZWrite",1);m.SetFloat("_Cull",2);m.renderQueue=2000;m.enableInstancing=true;EditorUtility.SetDirty(m);return m;}
  static CatalogAsset Prepare(Sign sign,Material snow){
   string id="alpine-sign-"+sign.index;var a=CatalogPreparation.Library().Find(id);if(a&&a.prefab){CatalogPreparation.RecordMetrics(a);return a;}
   string path=Source+sign.model+".fbx";var importer=AssetImporter.GetAtPath(path) as ModelImporter;Require(importer!=null,"missing FBX "+path);importer.importCameras=false;importer.importLights=false;importer.importAnimation=false;importer.globalScale=1;importer.isReadable=false;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;
   importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"SignPalette"),Palette());importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"SignPalette.001"),Palette());importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"SignSnow"),snow);importer.SaveAndReimport();var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);Require(model,"missing imported model");Require((CatalogValidation.BoundsOf(model).size-new Vector3(sign.size[0],sign.size[1],sign.size[2])).magnitude<.02f,"metres/axes mismatch "+id);
   var draft=CatalogPreparation.Draft(sign.name,CatalogKind.Landscape,AssetSource.ImportedModel,null,"User supplied Alpine_Mobile_Sign_Boards_12_Variants.blend; SHA256 "+Hash+". Collection "+sign.index+". Embedded READ ME treated as source data and not executed.");draft.id=id;draft.creationSourcePath="SourceAssets/AlpineSignBoards/Alpine_Mobile_Sign_Boards_12_Variants.blend";
   a=CatalogPreparation.Prepare(model,CatalogKind.Landscape,sign.name,1,Vector3.zero,AssetSource.ImportedModel,draft.provenance,draft);
   var root=PrefabUtility.LoadPrefabContents(AssetDatabase.GetAssetPath(a.prefab));try{
    var visual=root.transform.Find("VisualRoot");visual.localPosition=Vector3.zero;var raw=visual.GetChild(0);if(PrefabUtility.IsPartOfPrefabInstance(raw))PrefabUtility.UnpackPrefabInstance(PrefabUtility.GetOutermostPrefabInstanceRoot(raw.gameObject),PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);
    var frames=raw.GetComponentsInChildren<Transform>();Vector3 Basis(string n)=>root.transform.InverseTransformPoint(frames.Single(t=>t.name==n).position);var bx=Basis("BasisX");var by=Basis("BasisY");var bz=Basis("BasisZ");Require(Mathf.Abs(bx.x)>.99f&&Mathf.Abs(by.z)>.99f&&Mathf.Abs(bz.y)>.99f,"axis basis mismatch");
    foreach(var c in root.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c.gameObject);
    foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true)){r.sharedMaterial=r.name=="SnowCap"?snow:Palette();if(r.name=="SnowCap")r.name="SnowCap | removable decorative snow";}
    var b=CatalogValidation.BoundsOf(root);var proxy=new GameObject("Collision | sign envelope (review)");proxy.transform.SetParent(root.transform,false);var box=proxy.AddComponent<BoxCollider>();box.center=b.center;box.size=b.size;
    var mount=CatalogPreparation.Anchor(root.transform,"mount",AnchorRole.Connection,sign.index=="06"?bx*0+by*.21f+bz*1.8f:Vector3.zero);mount.interfaceId=sign.index=="06"?"wall-sign":"ground-sign";mount.transform.localRotation=Quaternion.LookRotation(-by,bz);
    var face=CatalogPreparation.Anchor(root.transform,"label-face",AnchorRole.Connection,by*(-.145f)+bz*(sign.index=="07"?2.05f:sign.index=="12"?1.85f:1.8f));face.transform.localRotation=Quaternion.LookRotation(by,bz);face.interfaceId="sign-label";
    foreach(var frame in frames.Where(t=>t.name.StartsWith("Basis",StringComparison.Ordinal)))UnityEngine.Object.DestroyImmediate(frame.gameObject);
    PrefabUtility.SaveAsPrefabAsset(root,AssetDatabase.GetAssetPath(a.prefab));
   }finally{PrefabUtility.UnloadPrefabContents(root);}
   a.tags=new[]{"alpine-sign","removable-snow",sign.index=="06"?"wall-mounted":"ground-mounted",sign.model.ToLowerInvariant()};a.minimumScale=.75f;a.maximumScale=1.5f;a.status=PreparationStatus.NeedsReview;a.visualReviewed=false;
   a.assumptions="Metres, Y-up. Original mounting origins retained. Body, evaluated mesh lettering (where supplied) and removable SnowCap are separate. Source FONT objects are preserved in the blend and exported as static mesh artwork. One shared opaque palette material plus existing toon snow. No lights, animation or runtime factories. Conservative sign-envelope collision requires handling review; wall variant requires a facade.";a.reviewNotes="Authorized scene placement; not published Ready. Review readability, collision clearance and Galaxy A07 cost.";CatalogPreparation.RecordMetrics(a);EditorUtility.SetDirty(a);return a;
  }
  static bool OverlapXZ(Bounds a,Bounds b,float gap=0)=>a.min.x<b.max.x+gap&&a.max.x>b.min.x-gap&&a.min.z<b.max.z+gap&&a.max.z>b.min.z-gap;
  static void Label(GameObject go,string label){var anchor=go.GetComponentsInChildren<AssetAnchor>().Single(a=>a.id=="label-face");var text=new GameObject("Label | retained gameplay destination").AddComponent<TextMesh>();text.transform.SetParent(anchor.transform,false);text.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");text.text=label;text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.fontSize=48;text.characterSize=.13f;text.color=new Color(.96f,.96f,.87f);text.GetComponent<MeshRenderer>().sharedMaterial=text.font.material;}
  static void FitLabels(Scene scene){
   foreach(var p in All<CatalogPlacement>(scene).Where(IsSign))foreach(var text in p.GetComponentsInChildren<TextMesh>()){
    text.font.RequestCharactersInTexture(text.text,text.fontSize,text.fontStyle);text.transform.localScale=Vector3.one;var b=text.GetComponent<MeshRenderer>().localBounds;float width=p.assetId=="alpine-sign-07"?2.4f:p.assetId=="alpine-sign-12"?1.5f:p.assetId=="alpine-sign-09"?1.65f:2.2f;float height=p.assetId=="alpine-sign-01"?.3f:p.assetId=="alpine-sign-02"?.23f:p.assetId=="alpine-sign-09"?.28f:p.assetId=="alpine-sign-07"?.95f:.65f;Require(b.size.x>.001f&&b.size.y>.001f,"invalid label bounds");text.transform.localScale=Vector3.one*Mathf.Min(1,Mathf.Min(width/b.size.x,height/b.size.y));
   }
  }
  static void Place(Scene scene,CatalogAsset[] entries){
   if(All<CatalogPlacement>(scene).Any(IsSign))return;
   var originals=All<Transform>(scene).Where(t=>t.name=="Sign board").Select(t=>t.parent).Distinct().OrderBy(t=>t.name).ToArray();Require(originals.Length==4,"expected four primitive signs");
   var terrain=All<Terrain>(scene).Single();var group=new GameObject("Sign boards | prepared alpine kit").transform;SceneManager.MoveGameObjectToScene(group.gameObject,scene);int number=0;
   var roads=All<Renderer>(scene).Where(r=>r.name=="Road | asphalt").Select(r=>r.bounds).ToArray();var blockers=All<Collider>(scene).Where(c=>c.enabled&&c.gameObject.activeInHierarchy&&!c.isTrigger&&!(c is TerrainCollider)&&!c.GetComponentInParent<SnowField>()&&!c.GetComponentInParent<MachineController>()).Select(c=>c.bounds).ToList();
   GameObject Put(int variant,Vector3 wanted,float yaw,string label=null,bool wall=false){
    var a=entries[variant-1];var go=(GameObject)PrefabUtility.InstantiatePrefab(a.prefab,scene);go.transform.SetParent(group,false);go.transform.rotation=Quaternion.Euler(0,yaw,0);
    if(wall){var mount=go.GetComponentsInChildren<AssetAnchor>().Single(x=>x.id=="mount");go.transform.rotation=Quaternion.LookRotation(Vector3.forward)*Quaternion.Inverse(mount.transform.localRotation);go.transform.position+=wanted-mount.transform.position;}
    else{bool found=false;for(int trial=0;trial<601;trial++){var p=wanted;if(trial>0){float radius=2+((trial-1)/24)*1.25f;float angle=(trial-1)%24*Mathf.PI*2/24;p+=new Vector3(Mathf.Cos(angle)*radius,0,Mathf.Sin(angle)*radius);}p.y=terrain.SampleHeight(p)+terrain.transform.position.y-.015f;go.transform.position=p;Physics.SyncTransforms();var b=go.GetComponentInChildren<Collider>().bounds;
      if(roads.Any(r=>OverlapXZ(b,r,.75f))||blockers.Any(o=>b.Intersects(o)))continue;found=true;break;}Require(found,"no clear roadside location for "+a.id);}
    go.GetComponent<CatalogPlacement>().placementId="pinefall-sign-"+(++number).ToString("D2");PrefabUtility.RecordPrefabInstancePropertyModifications(go.GetComponent<CatalogPlacement>());if(label!=null)Label(go,label);Physics.SyncTransforms();blockers.Add(go.GetComponentInChildren<Collider>().bounds);return go;
   }
   foreach(var old in originals){string label=old.GetComponentInChildren<TextMesh>().text;int variant=label.Contains("PINEFALL")||label.Contains("PARKING")?7:12;Put(variant,old.position,0,label);UnityEngine.Object.DestroyImmediate(old.gameObject);}
   Vector3[] points={new Vector3(-12,0,116),new Vector3(-74,0,113),new Vector3(-72,0,-51),new Vector3(120,0,-36),new Vector3(113,0,-54),Vector3.zero,new Vector3(-107,0,-58),new Vector3(116,0,73),new Vector3(75,0,112),new Vector3(-115,0,74),new Vector3(18,0,74),new Vector3(-12,0,-115)};
   float[] yaw={180,90,0,90,90,0,0,90,180,270,180,0};
   for(int i=0;i<12;i++){if(i==5)Put(6,new Vector3(-94,7,-102.96f),0,"FUEL + REPAIRS",true);else Put(i+1,points[i],yaw[i]);}
  }
  static string SnowData(SnowSeed seed)=>JsonUtility.ToJson(new SnowVolumeGrid{depth=seed.grid.depth,credit=seed.grid.credit,initialVolume=seed.grid.initialVolume,disposed=seed.grid.disposed,revision=seed.grid.revision,blocked=new bool[0]});
  static int RefreshMask(SnowField snow,Bounds[] bounds){var mask=(bool[])snow.seed.grid.blocked.Clone();int changed=0;Physics.SyncTransforms();for(int i=0;i<mask.Length;i++){float x=snow.seed.grid.X(i),z=snow.seed.grid.Z(i);// Reconcile the authored field mask after moved/deleted signs, including stale prior footprints.
   bool value=Physics.CheckBox(new Vector3(x,SnowField.Ground+.85f,z),new Vector3(SnowVolumeGrid.Cell*.45f,.65f,SnowVolumeGrid.Cell*.45f),Quaternion.identity,1<<0,QueryTriggerInteraction.Ignore);if(value!=mask[i]){mask[i]=value;changed++;}}if(changed>0){var seed=UnityEngine.Object.Instantiate(snow.seed);seed.name="Pinefall | prepared sign obstacles";seed.grid.blocked=mask;AssetDatabase.CreateAsset(seed,AssetDatabase.GenerateUniqueAssetPath(CatalogPreparation.Root+"/SceneData/SignBoardsSnowSeed.asset"));snow.seed=seed;EditorUtility.SetDirty(seed);EditorUtility.SetDirty(snow);}return changed;}
  static void Validate(Scene scene,CatalogAsset[] entries){SignWayfindingAuthoring.Validate(scene);var placed=All<CatalogPlacement>(scene).Where(IsSign).ToArray();Require(placed.Length>=12&&placed.Select(p=>p.placementId).Distinct().Count()==placed.Length,"unique sign placements required");// Latest user curation intentionally uses only the requested nine variants.
   Require(!All<Transform>(scene).Any(t=>t.name=="Sign board"||t.name=="Sign post"),"primitive signs remain");
   var terrain=All<Terrain>(scene).Single();var roads=All<Renderer>(scene).Where(r=>r.name=="Road | asphalt").Select(r=>r.bounds).ToArray();foreach(var p in placed){Require(PrefabUtility.IsPartOfPrefabInstance(p),"disconnected sign");Require(p.GetComponentsInChildren<Light>(true).Length==0,"unexpected sign light");foreach(var text in p.GetComponentsInChildren<TextMesh>()){var size=Vector3.Scale(text.GetComponent<MeshRenderer>().localBounds.size,text.transform.localScale);float maxWidth=p.assetId=="alpine-sign-07"?2.4f:p.assetId=="alpine-sign-12"?1.5f:2.2f;Require(size.x<=maxWidth+.005f&&size.y<=.955f,"destination label exceeds board");}if(p.assetId!="alpine-sign-06"){var b=p.GetComponentInChildren<Collider>().bounds;Require(!roads.Any(r=>OverlapXZ(b,r,.7f)),"sign obstructs road "+p.placementId);Require(Mathf.Abs(p.transform.position.y-(terrain.SampleHeight(p.transform.position)+terrain.transform.position.y-.015f))<.005f,"unseated sign "+p.placementId);}}
   var wall=placed.Single(p=>p.assetId=="alpine-sign-06");Require((wall.GetComponentsInChildren<AssetAnchor>().Single(a=>a.id=="mount").transform.position-new Vector3(-94,7,-102.96f)).magnitude<.005f,"wall mount missed facade");
   foreach(var a in entries){Require(CatalogValidation.Check(a).Ok,"catalog validation "+a.id);Require(a.prefab.GetComponentsInChildren<MeshRenderer>(true).Any(r=>r.name.StartsWith("SnowCap",StringComparison.Ordinal)),"missing removable snow");Require(a.prefab.GetComponentsInChildren<Camera>(true).Length==0,"camera leaked");}
  }
  static void Preview(CatalogAsset a){var p=new PreviewRenderUtility();try{var obj=UnityEngine.Object.Instantiate(a.prefab);p.AddSingleGO(obj);var b=CatalogValidation.BoundsOf(obj);p.camera.orthographic=true;p.camera.orthographicSize=Mathf.Max(b.extents.x,b.extents.y)*1.3f;p.camera.nearClipPlane=.03f;p.camera.farClipPlane=100;p.camera.transform.position=b.center+new Vector3(1,.4f,3)*b.size.magnitude;p.camera.transform.LookAt(b.center);p.camera.clearFlags=CameraClearFlags.SolidColor;p.camera.backgroundColor=new Color(.24f,.35f,.4f);p.ambientColor=new Color(.5f,.5f,.5f);p.lights[0].intensity=1.2f;p.lights[0].transform.rotation=p.camera.transform.rotation;p.BeginStaticPreview(new Rect(0,0,600,600));p.Render(true);var frame=p.EndStaticPreview();File.WriteAllBytes(Logs+"/"+a.id+".png",frame.EncodeToPNG());UnityEngine.Object.DestroyImmediate(frame);}finally{p.Cleanup();}}
  static void ScenePreviews(Scene scene){
   var camera=All<Camera>(scene).First();var placed=All<CatalogPlacement>(scene).Where(IsSign).ToArray();
   foreach(var p in placed){
    var face=p.GetComponentsInChildren<AssetAnchor>().Single(a=>a.id=="label-face").transform;camera.orthographic=false;camera.fieldOfView=50;camera.aspect=16f/9f;var roadReader=SignWayfindingAuthoring.Reader(scene,p.placementId);var terrain=All<Terrain>(scene).Single();camera.transform.position=new Vector3(roadReader.x,terrain.SampleHeight(roadReader)+terrain.transform.position.y+2,roadReader.z);camera.transform.LookAt(face.position+Vector3.up*.25f);
    var rt=new RenderTexture(1280,720,24);var previous=RenderTexture.active;Texture2D frame=null;
    try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;frame=new Texture2D(1280,720,TextureFormat.RGB24,false);frame.ReadPixels(new Rect(0,0,1280,720),0,0);frame.Apply();File.WriteAllBytes(Logs+"/scene-"+p.placementId+".png",frame.EncodeToPNG());}
    finally{camera.targetTexture=null;RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);if(frame)UnityEngine.Object.DestroyImmediate(frame);}
   }
  }
  [MenuItem("Snowglow/Asset intake/Import twelve alpine sign boards")]
  public static void Install(){
   Require(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play first");var scene=SceneManager.GetActiveScene();Require(scene.path==SceneValidation.ScenePath,"open Pinefall first");Directory.CreateDirectory(Logs);if(scene.isDirty)Require(EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-unsaved-before.unity",true),"unsaved backup failed");if(!File.Exists(Logs+"/Pinefall-before.unity"))File.Copy(scene.path,Logs+"/Pinefall-before.unity");
   var session=All<PrototypeSession>(scene).Single();var before=SnowData(session.Snow.seed);var oldSignBounds=All<CatalogPlacement>(scene).Where(IsSign).SelectMany(p=>p.GetComponentsInChildren<Collider>()).Select(c=>c.bounds).ToArray();var states=All<CatalogPlacement>(scene).Where(p=>!IsSign(p)&&!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,p=>p.assetId+"|"+Pose(p.transform));var fleet=session.Fleet.Select(m=>AssetDatabase.GetAssetPath(PrefabUtility.GetCorrespondingObjectFromSource(m.gameObject))).ToArray();
   var hashes=All<Terrain>(scene).Select(t=>AssetDatabase.GetAssetPath(t.terrainData)).Concat(session.Snow.GetComponentsInChildren<MeshFilter>().Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh))).Concat(new[]{AssetDatabase.GetAssetPath(session.Snow.seed)}).Where(p=>!string.IsNullOrEmpty(p)).Distinct().ToDictionary(p=>p,p=>AssetDatabase.GetAssetDependencyHash(p));
   var texture=AssetImporter.GetAtPath(Source+"Palette.png") as TextureImporter;Require(texture!=null,"palette import pending");texture.filterMode=FilterMode.Point;texture.mipmapEnabled=false;texture.wrapMode=TextureWrapMode.Clamp;texture.sRGBTexture=true;texture.textureCompression=TextureImporterCompression.Uncompressed;texture.SaveAndReimport();
   var data=JsonUtility.FromJson<Export>(File.ReadAllText(Source+"ExportMetrics.json"));Require(data.signs.Length==12,"12 source variants required");var entries=data.signs.Select(s=>Prepare(s,session.Snow.palette.snow)).ToArray();Place(scene,entries);SignWayfindingAuthoring.Apply(scene);FitLabels(scene);SignLabelDepthAuthoring.Apply(scene);Validate(scene,entries);int changed=RefreshMask(session.Snow,oldSignBounds.Concat(All<CatalogPlacement>(scene).Where(IsSign).SelectMany(p=>p.GetComponentsInChildren<Collider>()).Select(c=>c.bounds)).ToArray());Require(before==SnowData(session.Snow.seed),"snow accounting changed");AssetDatabase.SaveAssets();SceneValidation.Validate(scene);EditorSceneManager.MarkSceneDirty(scene);Require(EditorSceneManager.SaveScene(scene),"save failed");scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);
   entries=data.signs.Select(s=>CatalogPreparation.Library().Find("alpine-sign-"+s.index)).ToArray();Validate(scene,entries);SceneValidation.Validate(scene);MechanicsChecks.Run();session=All<PrototypeSession>(scene).Single();Require(before==SnowData(session.Snow.seed),"saved snow changed");foreach(var pair in hashes)Require(AssetDatabase.GetAssetDependencyHash(pair.Key)==pair.Value,"protected asset changed "+pair.Key);foreach(var p in All<CatalogPlacement>(scene).Where(p=>states.ContainsKey(p.placementId??"")))Require(states[p.placementId]==p.assetId+"|"+Pose(p.transform),"non-sign pose changed "+p.placementId);Require(fleet.SequenceEqual(session.Fleet.Select(m=>AssetDatabase.GetAssetPath(PrefabUtility.GetCorrespondingObjectFromSource(m.gameObject)))),"fleet changed");
   var report=new StringBuilder("PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". 12 catalog variants retained; only the requested sign types placed. Curated road-facing layout checked.\n");report.AppendLine("Saved sign placements: "+All<CatalogPlacement>(scene).Count(IsSign));foreach(var a in entries){var source=data.signs.Single(s=>"alpine-sign-"+s.index==a.id);Require(a.triangles==source.triangles,"triangle mismatch "+a.id+": "+a.triangles+" vs "+source.triangles);report.AppendLine(a.id+" "+a.displayName+": "+a.triangles+" triangles / "+a.renderers+" renderers; placements "+All<CatalogPlacement>(scene).Count(p=>p.assetId==a.id));Preview(a);}report.AppendLine("Placed mesh triangles: "+All<CatalogPlacement>(scene).Where(IsSign).Sum(p=>entries.Single(a=>a.id==p.assetId).triangles)+" (includes source lettering hidden by destination-aware scene overrides; authored TextMesh captions excluded). Two shared materials: opaque palette and existing toon snow. Snow obstacle flag changes: "+changed+"; depth/credit/volume, original terrain/snow assets, non-sign catalog poses and fleet preserved. Scene/19 ledger checks passed; no player-save writes or district rebake. Catalog remains Needs Review. Native prefab previews rendered; driving/touch/Android build/A07 performance untested.");ScenePreviews(scene);EditorSceneManager.OpenScene(SceneValidation.ScenePath);File.WriteAllText(Logs+"/Validation.txt",report.ToString());Debug.Log(report.ToString());
  }
